/**
 * Bật/tắt và cấu hình khung chat trên website + kết nối Telegram.
 *
 * This interface was referenced by `Config`'s JSON-Schema
 * via the `definition` "chat-settings".
 */
export interface ChatSetting {
  id: number;
  /**
   * Tắt = ẩn hẳn widget chat khỏi web.
   */
  enabled?: boolean | null;
  /**
   * Token từ @BotFather. Bí mật — chỉ admin xem/sửa. (fallback: TELEGRAM_BOT_TOKEN)
   */
  botToken?: string | null;
  /**
   * Dạng -100xxxxxxxxxx (nhóm bật Topics). (fallback: TELEGRAM_SALES_CHAT_ID)
   */
  salesChatId?: string | null;
  /**
   * Chuỗi bí mật xác thực webhook Telegram. (fallback: TELEGRAM_WEBHOOK_SECRET)
   */
  webhookSecret?: string | null;
  widgetTitle?: string | null;
  offlineMessage?: string | null;
  bubbleEnabled?: boolean | null;
  /**
   * Ngắn gọn 1–2 câu, có thể bôi đậm/nghiêng. Quá dài sẽ che mất nội dung trang.
   */
  bubbleMessage?: {
    root: {
      type: string;
      children: {
        type: any;
        version: number;
        [k: string]: unknown;
      }[];
      direction: ('ltr' | 'rtl') | null;
      format: 'left' | 'start' | 'center' | 'right' | 'end' | 'justify' | '';
      indent: number;
      version: number;
    };
    [k: string]: unknown;
  } | null;
  /**
   * Chờ bao lâu rồi mới bật bóng chào. 0 = hiện ngay.
   */
  bubbleDelay?: number | null;
  /**
   * Khách đã tắt bóng chào thì không làm phiền lại trong lượt đó.
   */
  bubbleOncePerSession?: boolean | null;
  /**
   * Hiện trong khung chat cùng với nút Đăng nhập / Đăng ký. Bỏ trống = dùng câu mặc định.
   */
  loginGreeting?: {
    root: {
      type: string;
      children: {
        type: any;
        version: number;
        [k: string]: unknown;
      }[];
      direction: ('ltr' | 'rtl') | null;
      format: 'left' | 'start' | 'center' | 'right' | 'end' | 'justify' | '';
      indent: number;
      version: number;
    };
    [k: string]: unknown;
  } | null;
  /**
   * Tin nhắn đầu tiên trong khung chat sau khi khách đăng nhập, ngay trước khi khách gõ câu hỏi.
   */
  welcomeMessage?: {
    root: {
      type: string;
      children: {
        type: any;
        version: number;
        [k: string]: unknown;
      }[];
      direction: ('ltr' | 'rtl') | null;
      format: 'left' | 'start' | 'center' | 'right' | 'end' | 'justify' | '';
      indent: number;
      version: number;
    };
    [k: string]: unknown;
  } | null;
  updatedAt?: string | null;
  createdAt?: string | null;
}
